21	static bool CheckNodeTensorNum(const Node &node, size_t nodeId)
22	{
23	    if (!node.operation) {
24	        ATB_LOG(ERROR) << " node[" << nodeId << "].operation is null";
25	        return false;
26	    }
27	    if (node.operation->GetInputNum() != node.inTensorIds.size()) {
28	        ATB_LOG(ERROR) << " node[" << nodeId << "].inTensorIds.size: " << node.inTensorIds.size()
29	                       << " != operation.inputNum: " << node.operation->GetInputNum();
30	        return false;
31	    }
32	    if (node.operation->GetOutputNum() != node.outTensorIds.size()) {
33	        ATB_LOG(ERROR) << " node[" << nodeId << "].outTensorIds.size: " << node.outTensorIds.size()
34	                       << " != operation.outputNum: " << node.operation->GetOutputNum();
35	        return false;
36	    }
37	    return true;
38	}
39	
40	static bool CheckNode(const Node &node, const size_t &nodeId, const uint64_t &totalTensorNum,
41	                      std::vector<bool> &tensorIsValued, std::vector<bool> &tensorIsUsed)
42	{
43	    if (!CheckNodeTensorNum(node, nodeId)) {
44	        return false;
45	    }
46	
47	    for (size_t i = 0; i < node.inTensorIds.size(); ++i) {
48	        uint32_t tensorId = node.inTensorIds.at(i);
49	        if (tensorId >= totalTensorNum) {
50	            ATB_LOG(ERROR) << " node[" << nodeId << "].inTensorIds[" << i << "]: " << tensorId
51	                           << " is invalid, need less than:" << totalTensorNum;
52	            return false;
53	        }
54	        if (!tensorIsValued.at(tensorId)) { // tensor尚未被赋值
55	            ATB_LOG(ERROR) << " node[" << nodeId << "].inTensorIds[" << i << "]: " << tensorId
56	                           << " is not assigned value yet, please check your graph.";
57	            return false;
58	        }
59	        tensorIsUsed.at(tensorId) = true;
60	    }
61	
62	    for (size_t i = 0; i < node.outTensorIds.size(); ++i) {
63	        uint32_t tensorId = node.outTensorIds.at(i);
64	        if (tensorId >= totalTensorNum) {
65	            ATB_LOG(ERROR) << " node[" << nodeId << "].outTensorIds[" << i << "]: " << tensorId
66	                           << " is invalid, need less than: " << totalTensorNum;
67	            return false;
68	        }
69	        if (tensorIsValued.at(tensorId)) { // tensor已被赋值
70	            bool writeInPlaceFlag = false;
71	            for (size_t j = 0; j < node.inTensorIds.size(); ++j) {
72	                if (node.inTensorIds.at(j) == tensorId) {
73	                    writeInPlaceFlag = true;
74	                    break;
75	                }
76	            }
77	            if (writeInPlaceFlag) {
78	                ATB_LOG(WARN) << " node[" << nodeId << "].outTensorIds[" << i << "]: " << tensorId
79	                              << " is write in place.";
80	                tensorIsUsed.at(tensorId) = false; // 原地写之后，tensor尚未被使用
81	            } else {
82	                ATB_LOG(WARN) << " node[" << nodeId << "].outTensorIds[" << i << "]: " << tensorId
83	                               << " has already been assigned value, please check your graph.";
84	            }
85	        } else {
86	            tensorIsValued.at(tensorId) = true;
87	        }
88	    }
89	    return true;
90	}
