92	static bool IsValidGraphName(const std::string &name)
93	{
94	    if (name.length() > MAX_GRAPH_NAME_LEN) {
95	        return false;
96	    }
97	    for (char c : name) {
98	        if (!isalnum(c) && c != '_') {
99	            return false;
100	        }
101	    }
102	    return true;
103	}
104	
105	static bool CheckAllTensor(const GraphParam &param, const std::vector<bool> &tensorIsValued,
106	                           const std::vector<bool> &tensorIsUsed)
107	{
108	    uint64_t totalTensorNum = param.inTensorNum + param.outTensorNum + param.internalTensorNum;
109	    for (size_t tensorId = param.inTensorNum; tensorId < totalTensorNum; tensorId++) {
110	        if (!tensorIsValued.at(tensorId)) {
111	            ATB_LOG(ERROR) << "graph tensorId: " << tensorId << " is not assigned value, please check your graph.";
112	            return false;
113	        }
114	    }
115	
116	    for (size_t tensorId = 0; tensorId < param.inTensorNum; tensorId++) {
117	        if (!tensorIsUsed.at(tensorId)) {
118	            ATB_LOG(WARN) << "graph intensorId: " << tensorId << " is not used.";
119	        }
120	    }
121	    uint64_t internalTensorStartIdx = param.inTensorNum + param.outTensorNum;
122	    for (size_t tensorId = internalTensorStartIdx; tensorId < totalTensorNum; tensorId++) {
123	        if (!tensorIsUsed.at(tensorId)) {
124	            ATB_LOG(WARN) << "graph internal tensorId: " << tensorId << " is not used.";
125	        }
126	    }
127	
128	    return true;
129	}
130	
131	static bool CheckGraphParam(const GraphParam &param)
132	{
133	    ATB_LOG(INFO) << "start check " << param.name << " graph.";
134	    if (!IsValidGraphName(param.name)) {
135	        ATB_LOG(ERROR) << "GraphParam.name: " << param.name << " is invalid.";
136	        return false;
137	    }
138	    const uint64_t totalTensorNum = param.inTensorNum + param.outTensorNum + param.internalTensorNum;
139	    if (param.inTensorNum > MAX_SVECTOR_SIZE || param.outTensorNum > MAX_SVECTOR_SIZE ||
140	        param.internalTensorNum > MAX_SVECTOR_SIZE) {
141	        ATB_LOG(ERROR) << "graph intensor: " << param.inTensorNum << ", outtensor: " << param.outTensorNum
142	                       << ", internaltensor: " << param.internalTensorNum << " need less than " << MAX_SVECTOR_SIZE;
143	        return false;
144	    }
145	    if (param.nodes.size() > MAX_NODE_NUM) {
146	        ATB_LOG(ERROR) << "graph nodes num is too large, nodes num: " << param.nodes.size()
147	                       << " > max nodes num: " << MAX_NODE_NUM;
148	        return false;
149	    }
150	    std::vector<bool> tensorIsValued(totalTensorNum, false); // true: 已被赋值, false: 尚未赋值
151	    std::vector<bool> tensorIsUsed(totalTensorNum, false);   // true: 已被使用, false: 尚未使用
152	    for (size_t tensorId = 0; tensorId < param.inTensorNum; tensorId++) {
153	        tensorIsValued.at(tensorId) = true;
154	    }
155	
156	    for (size_t nodeId = 0; nodeId < param.nodes.size(); ++nodeId) {
157	        const auto &node = param.nodes.at(nodeId);
158	        if (!CheckNode(node, nodeId, totalTensorNum, tensorIsValued, tensorIsUsed)) {
159	            ATB_LOG(ERROR) << "graph: " << param.name << " check failed.";
160	            return false;
161	        }
162	    }
163	
164	    if (!CheckAllTensor(param, tensorIsValued, tensorIsUsed)) {
165	        return false;
166	    }
167	
168	    ATB_LOG(INFO) << "check " << param.name << " graph success.";
169	    return true;
170	}
