172	static std::string JoinInts(const SVector<uint32_t> &ids)
173	{
174	    std::string ret;
175	    for (size_t i = 0; i < ids.size(); ++i) {
176	        if (i == 0) {
177	            ret.append(std::to_string(ids.at(i)));
178	        } else {
179	            ret.append(", " + std::to_string(ids.at(i)));
180	        }
181	    }
182	    return ret;
