185	static std::string GraphToString(const GraphParam &param)
186	{
187	    std::stringstream ss;
188	    ss << "inTensorNum:" << param.inTensorNum << ", outTensorNum:" << param.outTensorNum
189	       << ", internalTensorNum:" << param.internalTensorNum;
190	    for (size_t i = 0; i < param.nodes.size(); ++i) {
191	        ss << "\nnode[" << i << "]: operation:" << param.nodes.at(i).operation << ", inTensorIds:["
192	           << JoinInts(param.nodes.at(i).inTensorIds) << "], outTensorIds:[" << JoinInts(param.nodes.at(i).outTensorIds)
193	           << "]";
194	    }
195	    return ss.str();
196	}
