198	template <> Status CreateOperation(const GraphParam &opParam, Operation **operation)
199	{
200	    if (operation == nullptr) {
201	        ATB_LOG(ERROR) << "invalid param, operation is null";
202	        return ERROR_INVALID_PARAM;
203	    }
204	
205	    if (!CheckGraphParam(opParam)) {
206	        std::string graphString = GraphToString(opParam);
207	        ATB_LOG(ERROR) << "invalid param, graph param is invalid, graph:" << graphString;
208	        return ERROR_INVALID_GRAPH;
209	    }
210	    ATB_LOG(INFO) << GraphToString(opParam);
211	
212	    std::string name = opParam.name.empty() ? "GraphOperation" : opParam.name;
213	    *operation = new (std::nothrow) GraphOperation(name, opParam);
214	    if (*operation == nullptr) {
215	        ATB_LOG(ERROR) << "failed to new operation:" << name;
216	        return ERROR_OUT_OF_HOST_MEMORY;
217	    }
218	    return NO_ERROR;
219	}
