256	Status GraphOperation::InferShapeImpl(const SVector<TensorDesc> &inTensorDescs,
257	                                      SVector<TensorDesc> &outTensorDescs) const
258	{
259	    if (opGraph_.inferShapeFunc) {
260	        ATB_LOG(INFO) << GetLogPrefix() << "call user infer shape func";
261	        try {
262	            Status st = opGraph_.inferShapeFunc(inTensorDescs, outTensorDescs);
263	            if (st != NO_ERROR) {
264	                ATB_LOG(ERROR) << GetLogPrefix() << "user infer shape func fail, error: " << st;
265	                return st;
266	            }
267	        } catch (const std::exception &e) {
268	            ATB_LOG(ERROR) << GetLogPrefix() << "user infer shape func throw an exception:" << e.what();
269	            return ERROR_GRAPH_INFERSHAPE_FUNC_FAIL;
270	        }
271	        for (size_t i = 0; i < outTensorDescs.size(); i++) {
272	            TensorDesc desc = outTensorDescs.at(i);
273	            if (desc.shape.dimNum == 0 || desc.dtype == ACL_DT_UNDEFINED || desc.format == ACL_FORMAT_UNDEFINED) {
274	                ATB_LOG(ERROR) << GetLogPrefix() << "user infer shape result error, outTensorDesc[" << i
275	                               << "]: " << TensorUtil::TensorDescToString(desc);
276	                return ERROR_GRAPH_INFERSHAPE_FUNC_FAIL;
277	            }
278	        }
279	        return NO_ERROR;
280	    }
281	
282	    return InferShapeImplDefault(inTensorDescs, outTensorDescs);
283	}
