285	std::shared_ptr<Runner> GraphOperation::CreateRunner(Context &context) const
286	{
287	    std::shared_ptr<GraphRunner> runner = std::make_shared<GraphRunner>(GetName() + "Runner");
288	    if (!runner) {
289	        ATB_LOG(ERROR) << GetLogPrefix() << "make_shared GraphRunner fail";
290	        return std::shared_ptr<Runner>();
291	    }
292	
293	    GraphRunner::Graph &runnerGraph = runner->GetGraph();
294	    runnerGraph.inTensors.reserve(opGraph_.inTensorNum);
295	    runnerGraph.outTensors.reserve(opGraph_.outTensorNum);
296	    runnerGraph.internalTensors.reserve(opGraph_.internalTensorNum);
297	    runnerGraph.inTensors.resize(opGraph_.inTensorNum);
298	    runnerGraph.outTensors.resize(opGraph_.outTensorNum);
299	    runnerGraph.internalTensors.resize(opGraph_.internalTensorNum);
300	    runnerGraph.nodes.resize(opGraph_.nodes.size());
301	
302	    std::vector<Tensor *> fullTensorPtrs(opGraph_.inTensorNum + opGraph_.outTensorNum + opGraph_.internalTensorNum);
303	    BuildFullTensorPtrs(fullTensorPtrs, runnerGraph);
304	
305	    size_t nodeIdIdx = operationBaseIds_.size();
306	    std::vector<int64_t> nodeOperationIds = operationBaseIds_;
307	    nodeOperationIds.push_back(0);
308	
309	    for (size_t i = 0; i < runnerGraph.nodes.size(); ++i) {
310	        nodeOperationIds.at(nodeIdIdx) = static_cast<int64_t>(i);
311	        Status ret = CreateRunnerNode(i, runnerGraph, nodeOperationIds, fullTensorPtrs, context);
312	        if (ret != NO_ERROR) {
313	            return std::shared_ptr<Runner>();
314	        }
315	    }
316	
317	    ATB_LOG(INFO) << GetLogPrefix() << "create runner success";
318	    return runner;
319	}
320	
321	Status GraphOperation::CreateRunnerNode(const size_t nodeId, GraphRunner::Graph &runnerGraph,
322	                                        std::vector<int64_t> &nodeOperationIds,
323	                                        const std::vector<Tensor *> &fullTensorPtrs, Context &context) const
324	{
325	    auto &opNode = opGraph_.nodes.at(nodeId);
326	    GraphRunner::Node &runnerNode = runnerGraph.nodes.at(nodeId);
327	    if (!opNode.operation) {
328	        ATB_LOG(ERROR) << GetLogPrefix() << "node[" << nodeId << "] operation is invalid.";
329	        return ERROR_INVALID_PARAM;
330	    }
331	
332	    runnerNode.op.reset(opNode.operation, [](Operation *operation) { (void)operation; });
333	    OperationBase *opBase = dynamic_cast<OperationBase *>(opNode.operation);
334	    if (!opBase) {
335	        ATB_LOG(ERROR) << GetLogPrefix() << "node[" << nodeId << "] operation is not inherit from OperationBase";
336	        return ERROR_INVALID_PARAM;
337	    }
338	    opBase->runner_ = opBase->CreateRunner(context);
339	    runnerNode.runner = opBase->runner_;
340	    if (!runnerNode.runner) {
341	        ATB_LOG(ERROR) << GetLogPrefix() << "node[" << nodeId << "] runner is null.";
342	        return ERROR_INVALID_PARAM;
343	    }
344	    runnerNode.runner->SetRunnerInfo(runnerNode.op->GetName(), nodeOperationIds);
345	
346	    runnerNode.inTensorReshapeFuncs = opNode.inTensorReshapeFuncs;
347	    runnerNode.inTensors.reserve(opNode.inTensorIds.size());
348	    runnerNode.outTensors.reserve(opNode.outTensorIds.size());
349	    runnerNode.inTensorChunks = opNode.inTensorChunks;
350	    runnerNode.inTensors.resize(opNode.inTensorIds.size());
351	    runnerNode.outTensors.resize(opNode.outTensorIds.size());
352	
353	    for (size_t j = 0; j < opNode.inTensorIds.size(); ++j) {
354	        runnerNode.inTensors.at(j) = fullTensorPtrs.at(opNode.inTensorIds.at(j));
355	    }
356	    for (size_t k = 0; k < opNode.outTensorIds.size(); ++k) {
357	        runnerNode.outTensors.at(k) = fullTensorPtrs.at(opNode.outTensorIds.at(k));
358	    }
359	    return NO_ERROR;
360	}
