384	void GraphOperation::UsePluginOperations()
385	{
386	    for (size_t i = 0; i < opGraph_.nodes.size(); ++i) {
387	        auto &opNode = opGraph_.nodes.at(i);
388	        OperationBase *opBase = dynamic_cast<OperationBase *>(opNode.operation);
389	        if (!opBase) {
390	            Operation *oldOperation = opNode.operation;
391	            PluginOperation *pluginOp = new PluginOperation(oldOperation);
392	            if (!pluginOp) {
393	                ATB_LOG(ERROR) << GetLogPrefix() << "new PluginOperation Failed!";
394	                return;
395	            }
396	            ATB_LOG(INFO) << GetLogPrefix() << "node[" << i << "] operation is plugin operation, new PluginOperation";
397	            opNode.operation = pluginOp;
398	        }
399	    }
400	}
