402	Status GraphOperation::InferShapeImplDefault(const SVector<TensorDesc> &inTensorDescs,
403	                                             SVector<TensorDesc> &outTensorDescs) const
404	{
405	    ATB_LOG(INFO) << GetLogPrefix() << "InferShapeImplDefault start, inTensorDescsSize:" << inTensorDescs.size()
406	                  << ", outTensorDescs:" << outTensorDescs.size();
407	    std::vector<TensorDesc> totalTensorDescs(opGraph_.inTensorNum + opGraph_.outTensorNum + opGraph_.internalTensorNum);
408	    for (size_t i = 0; i < inTensorDescs.size(); ++i) {
409	        totalTensorDescs.at(i) = inTensorDescs.at(i);
410	    }
411	
412	    for (size_t nodeId = 0; nodeId < opGraph_.nodes.size(); ++nodeId) {
413	        auto &opNode = opGraph_.nodes.at(nodeId);
414	        SVector<TensorDesc> opInTensorDescs;
415	        opInTensorDescs.reserve(opNode.operation->GetInputNum());
416	        opInTensorDescs.resize(opNode.operation->GetInputNum());
417	        for (size_t i = 0; i < opNode.inTensorIds.size(); ++i) {
418	            uint32_t tensorId = opNode.inTensorIds.at(i);
419	            opInTensorDescs.at(i) = totalTensorDescs.at(tensorId);
420	            if (i < opNode.inTensorReshapeFuncs.size() && opNode.inTensorReshapeFuncs.at(i)) {
421	                Dims newShape;
422	                opNode.inTensorReshapeFuncs.at(i)(opInTensorDescs.at(i).shape, newShape);
423	                opInTensorDescs.at(i).shape = newShape;
424	            }
425	        }
426	
427	        SVector<TensorDesc> opOutTensorDescs;
428	        Status st = opNode.operation->InferShape(opInTensorDescs, opOutTensorDescs);
429	        if (st != 0) {
430	            ATB_LOG(ERROR) << GetLogPrefix() << "node[" << nodeId << "] infer shape fail, error code: " << st;
431	            return st;
432	        }
433	
434	        for (size_t i = 0; i < opNode.outTensorIds.size(); ++i) {
435	            uint32_t tensorId = opNode.outTensorIds.at(i);
436	            totalTensorDescs.at(tensorId) = opOutTensorDescs.at(i);
437	        }
438	    }
439	    outTensorDescs.reserve(opGraph_.outTensorNum);
440	    outTensorDescs.resize(opGraph_.outTensorNum);
441	    for (size_t i = 0; i < opGraph_.outTensorNum; ++i) {
442	        outTensorDescs.at(i) = totalTensorDescs.at(inTensorDescs.size() + i);
443	    }
444	
445	    return NO_ERROR;
446	}
