452	        fullTensorPtrs.at(offset++) = &runnerGraph.inTensors.at(i);
453	    }
454	    for (size_t i = 0; i < runnerGraph.outTensors.size(); ++i) {
455	        fullTensorPtrs.at(offset++) = &runnerGraph.outTensors.at(i);
456	    }
457	    for (size_t i = 0; i < runnerGraph.internalTensors.size(); ++i) {
458	        fullTensorPtrs.at(offset++) = &runnerGraph.internalTensors.at(i);
459	    }
460	}
