467	void GraphOperation::InitEmptyInTensorPerms()
468	{
469	    emptyInTensorPerms_.reserve(opGraph_.inTensorNum);
470	    emptyInTensorPerms_.resize(opGraph_.inTensorNum);
471	    for (size_t i = 0; i < emptyInTensorPerms_.size(); ++i) {
472	        emptyInTensorPerms_.at(i) = false;
473	    }
474	
475	    for (size_t nodeId = 0; nodeId < opGraph_.nodes.size(); ++nodeId) {
476	        auto &node = opGraph_.nodes.at(nodeId);
477	        if (!node.operation) {
478	            ATB_LOG(WARN) << GetLogPrefix() << "node[" << nodeId << "] operation is null";
479	            continue;
480	        }
481	        OperationBase *opBase = dynamic_cast<OperationBase *>(node.operation);
482	        if (!opBase) {
483	            ATB_LOG(INFO) << GetLogPrefix() << "node[" << nodeId << "] operation is not OperationBase";
484	            continue;
485	        }
486	
487	        SVector<bool> childOpEmptyInTensorPerms = opBase->GetEmptyInTensorPermissions();
488	        if (childOpEmptyInTensorPerms.size() != node.inTensorIds.size()) {
489	            ATB_LOG(WARN) << GetLogPrefix() << "node[" << nodeId
490	                          << "] childOpEmptyInTensorPerms.size:" << childOpEmptyInTensorPerms.size()
491	                          << " != inTensorIds.size:" << node.inTensorIds.size();
492	            continue;
493	        }
494	
495	        for (size_t i = 0; i < childOpEmptyInTensorPerms.size(); ++i) {
496	            uint32_t inTensorId = node.inTensorIds.at(i); // graph in tensor id in range [0, inTensorNum)
497	            if (childOpEmptyInTensorPerms.at(i) && inTensorId < emptyInTensorPerms_.size()) {
498	                emptyInTensorPerms_.at(inTensorId) = true;
499	                ATB_LOG(INFO) << GetLogPrefix() << "node[" << nodeId << "] " << node.operation->GetName()
500	                              << " inTensor[" << i << "] is allow empty";
501	            }
502	        }
503	    }
504	    ATB_LOG(INFO) << GetLogPrefix() << "emptyInTensorPerms:" << emptyInTensorPerms_;
505	}
506	
507	SVector<bool> GraphOperation::GetEmptyOutTensorPermissions() const
508	{
509	    return emptyOutTensorPerms_;
510	}
