512	void GraphOperation::InitEmptyOutTensorPerms()
513	{
514	    emptyOutTensorPerms_.reserve(opGraph_.outTensorNum);
515	    emptyOutTensorPerms_.resize(opGraph_.outTensorNum);
516	    for (size_t i = 0; i < emptyOutTensorPerms_.size(); ++i) {
517	        emptyOutTensorPerms_.at(i) = false;
518	    }
519	 
520	    for (size_t nodeId = 0; nodeId < opGraph_.nodes.size(); ++nodeId) {
521	        auto &node = opGraph_.nodes.at(nodeId);
522	        if (!node.operation) {
523	            ATB_LOG(WARN) << GetLogPrefix() << "node[" << nodeId << "] operation is null";
524	            continue;
525	        }
526	        OperationBase *opBase = dynamic_cast<OperationBase *>(node.operation);
527	        if (!opBase) {
528	            ATB_LOG(INFO) << GetLogPrefix() << "node[" << nodeId << "] operation is not OperationBase";
529	            continue;
530	        }
531	 
532	        SVector<bool> childOpEmptyOutTensorPerms = opBase->GetEmptyOutTensorPermissions();
533	        if (childOpEmptyOutTensorPerms.size() != node.outTensorIds.size()) {
534	            ATB_LOG(WARN) << GetLogPrefix() << "node[" << nodeId
535	                          << "] childOpEmptyOutTensorPerms.size:" << childOpEmptyOutTensorPerms.size()
536	                          << " != outTensorIds.size:" << node.outTensorIds.size();
537	            continue;
538	        }
539	 
540	        for (size_t i = 0; i < childOpEmptyOutTensorPerms.size(); ++i) {
541	            uint32_t outTensorId = node.outTensorIds.at(i);
542	            // graph out tensor id in range [inTensorNum, inTensorNum + outTensorNum)
543	            if (childOpEmptyOutTensorPerms.at(i) && outTensorId >= opGraph_.inTensorNum &&
544	                outTensorId < opGraph_.inTensorNum + opGraph_.outTensorNum) {
545	                emptyOutTensorPerms_.at(outTensorId - opGraph_.inTensorNum) = true;
546	                ATB_LOG(INFO) << GetLogPrefix() << "node[" << nodeId << "] " << node.operation->GetName()
547	                              << " outTensor[" << i << "] is allow empty";
548	            }
549	        }
550	    }
551	    ATB_LOG(INFO) << GetLogPrefix() << "emptyOutTensorPerms:" << emptyOutTensorPerms_;
552	}
