557	    graphJson["param"] = "";
558	    for (size_t i = 0; i < opGraph_.nodes.size(); i++) {
559	        nlohmann::json graphNodeJson;
560	        auto &node = opGraph_.nodes.at(i);
561	        nlohmann::json tmpNodeJson = "";
562	        OperationBase *opBase = dynamic_cast<OperationBase *>(node.operation);
563	
564	        if (opBase) {
