569	            tmpNodeJson = tmpJson;
570	        }
571	
572	        graphNodeJson = tmpNodeJson;
573	        ATB_LOG(INFO) << GetLogPrefix() << "node[" << i << "] json string:" << graphNodeJson.dump();
574	
575	        graphNodeJson["inTensorIds"] = SVectorToVector(node.inTensorIds);
576	        graphNodeJson["outTensorIds"] = SVectorToVector(node.outTensorIds);
577	        graphJson["nodes"].emplace_back(graphNodeJson);
