228	            ATB_LOG(ERROR) << "RunnerVariantPack error! inTensor size: " << runnerVariantPack.inTensors.size()
229	                           << ", isInTensorCanFree size: " << runnerVariantPack.isInTensorCanFree.size()
230	                           << ", outTensor size: " << runnerVariantPack.outTensors.size()
231	                           << ", isOutTensorNeedMalloc size: " << runnerVariantPack.isOutTensorNeedMalloc.size();
232	            return ERROR_INVALID_PARAM;
233	        }
234	
235	        for (size_t i = 0; i < runnerGraph_.inTensors.size(); i++) {
236	            runnerGraph_.isInTensorCanFree[&runnerGraph_.inTensors.at(i)] = runnerVariantPack.isInTensorCanFree.at(i);
237	        }
238	        for (size_t i = 0; i < runnerGraph_.outTensors.size(); i++) {
239	            runnerGraph_.isOutTensorNeedMalloc[&runnerGraph_.outTensors.at(i)] =
240	                runnerVariantPack.isOutTensorNeedMalloc.at(i);
241	        }
242	        runnerGraph_.Init();
243	    }
244	    return NO_ERROR;
245	}
