247	void GraphRunner::UpdateOutTensorDeviceData(RunnerVariantPack &runnerVariantPack)
248	{
249	    for (size_t i = 0; i < runnerGraph_.outTensors.size(); i++) {
250	        Tensor *outTensor = &runnerGraph_.outTensors.at(i);
251	        auto it = runnerGraph_.isOutTensorNeedMalloc.find(outTensor);
252	        if (it == runnerGraph_.isOutTensorNeedMalloc.end()) {
253	            ATB_LOG(ERROR) << GetLogPrefix() << "outTensor[" << i << "] isOutTensorNeedMalloc not found";
254	            if (!runnerVariantPack.outTensors.at(i).deviceData) {
255	                runnerVariantPack.outTensors.at(i).deviceData = outTensor->deviceData;
256	            }
257	        } else if (it->second) {
258	            runnerVariantPack.outTensors.at(i).deviceData = outTensor->deviceData;
259	        }
260	    }
261	}
